import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const s=JSON.parse('{"title":"构建工具选型","description":"","frontmatter":{"title":"构建工具选型","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/tooling/build-tool.md","filePath":"frontend/decisions/tooling/build-tool.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/tooling/build-tool.md"};function o(l,t,h,n,c,p){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="构建工具选型" tabindex="-1">构建工具选型 <a class="header-anchor" href="#构建工具选型" aria-label="Permalink to &quot;构建工具选型&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>构建工具同时影响本地反馈、模块转换、生产分包、插件生态、调试和迁移。选型应以应用和框架的受支持路径为前提，用真实模块图和代表性构建验证，而不是引用一个空项目的启动速度。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>新项目通常可以采用框架官方推荐工具；遗留项目则可能积累自定义 loader、插件、全局注入和非标准模块。更换工具的收益需要覆盖迁移这些行为、验证产物语义和培训排障的成本。</p><p>具体打包、分包和 Vite 使用参见<a href="/frontend/guide/engineering/tooling/bundling">打包、分包与 Tree Shaking</a>与<a href="/frontend/guide/engineering/tooling/vite">Vite 开发与构建体系</a>。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>被选框架、TypeScript、CSS、资产和测试工具有稳定集成；</li><li>产物满足目标浏览器、CSP、Source Map 和部署协议；</li><li>必需的模块格式、Web Worker、SSR 和库构建行为可验证；</li><li>供应链、插件来源和许可证符合组织要求；</li><li>CI 环境和开发机平台均受支持。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>测量冷启动、编辑到页面更新、生产构建、峰值内存、缓存命中、产物体积和 Source Map 可用性；同时评估插件替代、配置可理解性、框架官方支持、排障能力和迁移工作量。</p><p>每项性能数据都要注明机器、缓存状态、模块规模和测量脚本，否则无法复现。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-vite-体系" tabindex="-1">3.1 Vite 体系 <a class="header-anchor" href="#_3-1-vite-体系" aria-label="Permalink to &quot;3.1 Vite 体系&quot;">​</a></h3><p>以原生模块开发服务器和生产构建流水线提供快速反馈，框架集成成熟，适合大多数现代应用和库。复杂遗留转换、特定插件语义和超大型仓库仍需原型验证。</p><h3 id="_3-2-webpack-体系" tabindex="-1">3.2 Webpack 体系 <a class="header-anchor" href="#_3-2-webpack-体系" aria-label="Permalink to &quot;3.2 Webpack 体系&quot;">​</a></h3><p>拥有长期积累的 loader、插件和企业配置，适合依赖其特殊行为且迁移收益不足的遗留系统。配置和增量反馈可能成为成本，但通过持久缓存和模块治理也能改善。</p><h3 id="_3-3-兼容-webpack-生态的高性能工具" tabindex="-1">3.3 兼容 Webpack 生态的高性能工具 <a class="header-anchor" href="#_3-3-兼容-webpack-生态的高性能工具" aria-label="Permalink to &quot;3.3 兼容 Webpack 生态的高性能工具&quot;">​</a></h3><p>Rspack 等方案追求更快构建并兼容部分现有配置，适合迁移成本受 Webpack 生态约束的大型项目。兼容不是绝对等价，关键 loader、插件和产物需逐项验证。</p><h3 id="_3-4-框架托管的构建配置" tabindex="-1">3.4 框架托管的构建配置 <a class="header-anchor" href="#_3-4-框架托管的构建配置" aria-label="Permalink to &quot;3.4 框架托管的构建配置&quot;">​</a></h3><p>元框架通常封装底层工具并保证支持路径。若已经采用元框架，应优先在其公开扩展点内配置，而不是单独替换内部构建器；否则升级风险会转由团队承担。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是包含 3500 个模块的 Vue 3 新运营平台，同时有一个 9 年历史的 Webpack 5 应用，后者依赖 14 个自定义 loader 或插件。</p><table tabindex="0"><thead><tr><th>维度</th><th>新项目 Vite</th><th>遗留项目保留 Webpack</th><th>遗留项目直接迁 Vite</th><th>兼容型迁移</th></tr></thead><tbody><tr><td>新项目反馈</td><td>最好</td><td>无必要使用旧栈</td><td>最好</td><td>取决于集成</td></tr><tr><td>遗留行为兼容</td><td>不适用</td><td>已验证</td><td>需重写 14 项</td><td>可复用部分配置</td></tr><tr><td>迁移风险</td><td>低</td><td>低</td><td>高</td><td>中</td></tr><tr><td>生产产物</td><td>原型通过</td><td>当前基线</td><td>需完整回归</td><td>需完整回归</td></tr><tr><td>长期统一</td><td>新旧双轨</td><td>新旧双轨</td><td>最终统一</td><td>可能形成过渡轨</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>新 Vue 3 平台采用 Vite，这是框架生态的受支持路径，代表性原型满足开发和生产门槛。遗留应用暂时保留 Webpack，并先替换自定义插件、建立构建基线；不把两个系统必须立即统一作为硬目标。</p><p>只有当遗留项目的构建等待成为实测瓶颈，且关键插件已有替代时，再分别试验 Vite 或兼容型工具。这样把“新项目选型”和“旧项目迁移”分成两个决定。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>团队短期维护两套工具，但避免将新项目拖回旧约束，也避免一次高风险迁移。需要统一的是模块规范、浏览器目标、Source Map、环境变量安全和 CI 验收，而不是所有配置文件长得一样。</p><p>构建工具升级要验证运行语义：动态导入、CSS 顺序、Worker、资源 URL、Tree Shaking 和错误栈。构建成功只能证明产物生成，不能证明行为等价。</p><p>退出成本来自私有插件 API 和工具特有导入语法。优先使用标准 ESM、框架官方插件和独立转换脚本，可降低锁定。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要用空项目 benchmark 决定大型应用迁移。</li><li>不要为统一工具而忽略遗留插件的业务语义。</li><li>不要在元框架不支持的情况下替换其内部构建器。</li><li>构建慢应先定位模块图、类型检查、测试或插件瓶颈。</li><li>生产构建更快不代表运行产物更小或更正确。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>新 Vue 平台和遗留 Webpack 应用如何选择构建工具</td></tr><tr><td>硬约束</td><td>标准 ESM；Source Map 可用；Worker 和旧浏览器目标通过；CI 可复现</td></tr><tr><td>候选</td><td>全部 Webpack、全部 Vite、双轨、兼容型迁移</td></tr><tr><td>决定</td><td>新项目 Vite；遗留 Webpack 先治理后再评估迁移</td></tr><tr><td>证据</td><td>3500 模块原型；14 个自定义插件清单；生产回放和产物检查</td></tr><tr><td>接受代价</td><td>短期两套工具和培训材料</td></tr><tr><td>成功指标</td><td>热更新 P75、冷构建、CI 构建、内存、产物和 Source Map 成功率</td></tr><tr><td>退出路径</td><td>标准 ESM；自定义转换逐步独立；不新增 Webpack 私有 loader</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>遗留构建 P75 超过 10 分钟、每月因旧插件产生两次以上故障、关键插件替代率达到 90%，或现有工具停止安全维护时复查。新项目若出现无法满足的生产语义或框架官方支持变化，也应单独复查，而不是强迫两个项目同步。</p>',37)])])}const u=a(i,[["render",o]]);export{s as __pageData,u as default};
